<?php
declare(strict_types=1);
require __DIR__.'/../private/form-utils.php';
require __DIR__.'/../private/site.php';
require __DIR__.'/../private/careers.php';
header('Cache-Control: no-store');

$config=careers_load_config();
$jobs=careers_public_jobs($config);
$selectedJob=careers_clean((string)($_GET['job']??''),100);
$message=''; $error='';

if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (function_exists('evosys_honeypot') && evosys_honeypot()) { header('Location: ./?sent=1',true,303); exit; }
    if (function_exists('evosys_too_fast') && evosys_too_fast()) { $error='Please wait a moment and submit again.'; }
    $jobId=careers_clean((string)($_POST['job_id']??''),100);
    $job=careers_find_job($config,$jobId);
    if (!$error && (!$job || ($job['status']??'')!=='published')) $error='That role is no longer accepting applications.';
    $full=careers_clean((string)($_POST['full_name']??''),160);
    $email=careers_clean((string)($_POST['email']??''),180);
    $phone=careers_clean((string)($_POST['phone']??''),50);
    $city=careers_clean((string)($_POST['city_state']??''),120);
    $salesExp=careers_clean((string)($_POST['sales_experience']??''),80);
    $interest=careers_clean((string)($_POST['interest']??''),3000);
    if (!$error && ($full==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen(preg_replace('/\D/','',$phone))<10 || $city==='' || $salesExp==='' || $interest==='')) $error='Please complete all required fields.';
    if (!$error && empty($_POST['ack_1099']) && stripos((string)($job['employment_type']??''),'1099')!==false) $error='Please confirm that you understand this is a 1099 commission-based opportunity.';
    if (!$error) {
        try {
            $resume=careers_store_resume($_FILES['resume']??[], 'tmp-'.bin2hex(random_bytes(4)));
            // Rename resume after the authoritative application id exists.
            $result=careers_store_application([
                'job_id'=>$jobId,'job_title'=>(string)$job['title'],'full_name'=>$full,'email'=>$email,'phone'=>$phone,'city_state'=>$city,
                'linkedin'=>$_POST['linkedin']??'','current_role'=>$_POST['current_role']??'','sales_experience'=>$salesExp,
                'b2b_experience'=>$_POST['b2b_experience']??'','saas_experience'=>$_POST['saas_experience']??'','profile_type'=>$_POST['profile_type']??'',
                'source'=>$_POST['source']??'EvoSys Website','start_timing'=>$_POST['start_timing']??'','interest'=>$interest,'ack_1099'=>!empty($_POST['ack_1099'])
            ], $resume);
            $app=$result['application'];
            // If a resume was uploaded to a temporary safe filename, move it to the permanent application id.
            if (!empty($resume['path'])) {
                $old=careers_base_dir().'/'.$resume['path']; $ext=pathinfo($old,PATHINFO_EXTENSION); $newRel='resumes/'.$app['application_id'].'.'.$ext; $new=careers_base_dir().'/'.$newRel;
                if (is_file($old) && @rename($old,$new)) {
                    $app['resume']['path']=$newRel; careers_atomic_json_write(careers_application_path($app['application_id']),$app);
                }
            }
            header('Location: ./?sent=1&ref='.rawurlencode((string)$app['application_id']),true,303); exit;
        } catch(RuntimeException $e){
            // These are the curated, user-facing refusals thrown by
            // careers_store_resume/careers_store_application ("Resume must be a
            // PDF, DOC, or DOCX file."). Safe to show.
            $error=$e->getMessage();
        } catch(Throwable $e){
            // Anything else is a programming or environment fault, and its
            // message can carry a filesystem path or an internal detail. The
            // visitor gets a generic sentence; the operator gets the real error
            // in the PHP log.
            error_log('careers application failed: '.$e->getMessage());
            $error='We could not record your application right now. Please try again shortly.';
        }
    }
}

$sent=isset($_GET['sent']); $ref=careers_clean((string)($_GET['ref']??''),80);
site_head('Careers | EvoSys Pro','Explore current opportunities with EvoSys Pro and apply online.');
site_nav();
?>
