option></select></div><div class="field"><label>B2B Sales Experience?</label><select name="b2b_experience"><option value="">Choose one</option><option>Yes</option><option>No</option></select></div><div class="field"><label>SaaS / Technology Sales Experience?</label><select name="saas_experience"><option value="">Choose one</option><option>Yes</option><option>No</option></select></div><div class="field"><label>How did you hear about us?</label><select name="source"><option>EvoSys Website</option><option>Indeed</option><option>LinkedIn</option><option>Referral</option><option>Other</option></select></div><div class="field"><label>How soon could you start?</label><select name="start_timing"><option value="">Choose one</option><option>Immediately</option><option>Within 2 weeks</option><option>Within 30 days</option><option>More than 30 days</option></select></div><div class="field full"><label>Why are you interested in this opportunity? *</label><textarea name="interest" required></textarea></div><div class="field full"><label>Resume (optional)</label><input type="file" name="resume" accept=".pdf,.doc,.docx"><div class="form-help">PDF, DOC, or DOCX. Maximum 5 MB.</div></div><div class="field full" id="ackWrap"><label style="display:flex;gap:10px;align-items:flex-start"><input type="checkbox" name="ack_1099" value="1" style="width:auto;margin-top:2px"><span>I understand that the Sales Consultant opportunity is a 1099 independent-contractor, commission-based role with no base salary.</span></label></div><div class="field full"><button class="career-btn gold" type="submit" style="width:100%">Submit Application →</button><div class="form-help" style="text-align:center;margin-top:8px">Do not submit Social Security numbers, banking information, or other sensitive identity documents through this form.</div></div></div></form></div></div></section>
