<script>
(function(){
const cards=[...document.querySelectorAll('.job-card')], dept=document.getElementById('deptFilter'), loc=document.getElementById('locationFilter'), typ=document.getElementById('typeFilter'), jobSelect=document.getElementById('job_id');
function fill(select,attr){[...new Set(cards.map(c=>c.dataset[attr]).filter(Boolean))].sort().forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;select.appendChild(o);});}
fill(dept,'dept');fill(loc,'location');fill(typ,'type');
function filter(){cards.forEach(c=>{c.hidden=!!((dept.value&&c.dataset.dept!==dept.value)||(loc.value&&c.dataset.location!==loc.value)||(typ.value&&c.dataset.type!==typ.value));});}
[dept,loc,typ].forEach(x=>x.addEventListener('change',filter));
document.querySelectorAll('.details-role').forEach(b=>b.addEventListener('click',()=>{const x=document.getElementById('details-'+b.dataset.job);x.hidden=!x.hidden;b.textContent=x.hidden?'View Details':'Hide Details';}));
document.querySelectorAll('.apply-role').forEach(b=>b.addEventListener('click',()=>{jobSelect.value=b.dataset.job;document.getElementById('apply').scrollIntoView({behavior:'smooth'});setTimeout(()=>jobSelect.focus(),450);}));
})();
</script>
